import React, { useEffect, useRef, useState } from 'react';
import {
  Alert,
  GestureResponderEvent,
  Pressable,
  StyleSheet,
  Text,
  View,
} from 'react-native';

import {
  cancelRecording,
  requestPermissions,
  startRecording,
  stopRecording,
} from '../audio/recorder';

declare const require: (moduleName: string) => unknown;

export interface AudioUpload {
  uri: string;
  durationMs: number;
  mime: 'audio/m4a';
}

export interface HoldToRecordButtonProps<Message = unknown> {
  chatId: string;
  onSent: (message: Message) => void;
  sendAudio?: (chatId: string, audio: AudioUpload) => Promise<Message>;
}

type SendAudio<Message> = (chatId: string, audio: AudioUpload) => Promise<Message>;

const CANCEL_DISTANCE = 80;
const MIN_DURATION_MS = 500;

function getDefaultSendAudio<Message>(): SendAudio<Message> | null {
  try {
    const module = require('../api/client') as {
      sendAudio?: SendAudio<Message>;
      client?: { sendAudio?: SendAudio<Message> };
      default?: { sendAudio?: SendAudio<Message> };
    };
    return module.sendAudio ?? module.client?.sendAudio?.bind(module.client) ??
      module.default?.sendAudio?.bind(module.default) ?? null;
  } catch {
    return null;
  }
}

export function HoldToRecordButton<Message = unknown>({
  chatId,
  onSent,
  sendAudio,
}: HoldToRecordButtonProps<Message>): React.JSX.Element {
  const [isRecording, setIsRecording] = useState(false);
  const [isCancelled, setIsCancelled] = useState(false);
  const startX = useRef(0);
  const pressId = useRef(0);
  const recordingStartedAt = useRef(0);
  const recordingReady = useRef(false);

  useEffect(() => () => {
    pressId.current += 1;
    if (recordingReady.current) {
      recordingReady.current = false;
      void cancelRecording();
    }
  }, []);

  const handlePressIn = async (event: GestureResponderEvent): Promise<void> => {
    const currentPress = pressId.current + 1;
    pressId.current = currentPress;
    startX.current = event.nativeEvent.pageX;
    recordingReady.current = false;
    setIsCancelled(false);
    setIsRecording(true);

    try {
      const granted = await requestPermissions();
      if (!granted) {
        if (pressId.current === currentPress) setIsRecording(false);
        Alert.alert('Нет доступа к микрофону', 'Разрешите доступ к микрофону в настройках устройства.');
        return;
      }
      if (pressId.current !== currentPress) return;
      await startRecording();
      if (pressId.current !== currentPress) {
        await cancelRecording();
        return;
      }
      recordingReady.current = true;
      recordingStartedAt.current = Date.now();
    } catch {
      if (pressId.current === currentPress) setIsRecording(false);
      Alert.alert('Не удалось начать запись', 'Попробуйте ещё раз.');
    }
  };

  const handleMove = (event: GestureResponderEvent): void => {
    if (!isRecording) return;
    setIsCancelled(startX.current - event.nativeEvent.pageX > CANCEL_DISTANCE);
  };

  const handlePressOut = async (): Promise<void> => {
    pressId.current += 1;
    setIsRecording(false);

    if (!recordingReady.current) return;
    recordingReady.current = false;
    if (isCancelled) {
      await cancelRecording();
      setIsCancelled(false);
      return;
    }

    try {
      const result = await stopRecording();
      const measuredDuration = Math.max(result.durationMs, Date.now() - recordingStartedAt.current);
      if (measuredDuration < MIN_DURATION_MS) return;
      const upload = sendAudio ?? getDefaultSendAudio<Message>();
      if (!upload) throw new Error('Audio API is unavailable');
      const message = await upload(chatId, {
        uri: result.uri,
        durationMs: result.durationMs || measuredDuration,
        mime: 'audio/m4a',
      });
      onSent(message);
    } catch {
      Alert.alert('Не удалось отправить аудио', 'Проверьте подключение и попробуйте ещё раз.');
    } finally {
      setIsCancelled(false);
    }
  };

  return (
    <View style={styles.wrapper}>
      {isRecording && (
        <Text style={[styles.hint, isCancelled && styles.cancelHint]}>
          Отпустите, чтобы отменить
        </Text>
      )}
      <Pressable
        accessibilityLabel='Удерживайте для записи аудиосообщения'
        accessibilityRole='button'
        onPressIn={(event) => void handlePressIn(event)}
        onPressOut={() => void handlePressOut()}
        onTouchMove={handleMove}
        style={({ pressed }) => [
          styles.button,
          pressed && styles.buttonPressed,
          isCancelled && styles.buttonCancelled,
        ]}
      >
        <Text style={styles.microphone}>●</Text>
        <View style={styles.microphoneStem} />
      </Pressable>
    </View>
  );
}

const styles = StyleSheet.create({
  wrapper: { alignItems: 'center', flexDirection: 'row' },
  hint: { color: '#70808b', fontSize: 13, marginRight: 10 },
  cancelHint: { color: '#e53935' },
  button: {
    alignItems: 'center',
    backgroundColor: '#3390ec',
    borderRadius: 24,
    height: 48,
    justifyContent: 'center',
    width: 48,
  },
  buttonPressed: { opacity: 0.82, transform: [{ scale: 1.06 }] },
  buttonCancelled: { backgroundColor: '#e53935' },
  microphone: { color: '#ffffff', fontSize: 20, height: 21, lineHeight: 19 },
  microphoneStem: {
    backgroundColor: '#ffffff',
    borderBottomLeftRadius: 4,
    borderBottomRightRadius: 4,
    height: 7,
    marginTop: -4,
    width: 3,
  },
});

export default HoldToRecordButton;
